-- Demo data: the test.customer@ofs.com customer (password testcustomer) and the
-- manager@ofs.com manager (password manager123), with past orders, deliveries,
-- robot runs, notifications, declined payments, stock changes and the catalog.
--
-- Like the other init files, this only runs on a fresh database volume.
-- Recreate it with: docker compose down -v && docker compose up --build
-- Nobody is signed in when the app starts. No saved Stripe customers are included,
-- so checkout works with whichever Stripe test keys are in .env.

BEGIN;

-- Replaces the starter catalog and default settings with the demo copies.
TRUNCATE users,customer,manager,address,category,product,shoppingcart,cartitems,orders,orderitem,payment,robot,deliveryrun,delivery,notification,failedpayment,auditlog,pricehistory,transactions,globalsettings CASCADE;


-- Data for Name: users; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: address; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: auditlog; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: category; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: product; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: shoppingcart; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: cartitems; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: customer; Type: TABLE DATA; Schema: public; Owner: -

-- Data for Name: robot; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: deliveryrun; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: orders; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: delivery; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: failedpayment; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: globalsettings; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: manager; Type: TABLE DATA; Schema: public; Owner: -

-- Data for Name: notification; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: orderitem; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: payment; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: pricehistory; Type: TABLE DATA; Schema: public; Owner: -


-- Data for Name: transactions; Type: TABLE DATA; Schema: public; Owner: -


-- Name: pricehistory_price_history_id_seq; Type: SEQUENCE SET; Schema: public; Owner: -

SELECT pg_catalog.setval('public.pricehistory_price_history_id_seq', 1, false);


-- Move every date forward so the newest order is from today, keeping the gaps
-- between events. The reports' default date ranges then always have data.
DO $$
DECLARE
  shift interval;
  col record;
BEGIN
  SELECT now() - greatest(
    (SELECT max(updated_at) FROM orders),
    (SELECT max(updated_at) FROM delivery),
    (SELECT max(created_at) FROM notification),
    (SELECT max(created_at) FROM transactions)) INTO shift;
  FOR col IN
    SELECT table_name, column_name FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name IN ('users','customer','manager','address','category','product','shoppingcart','cartitems','orders','orderitem','payment','robot','deliveryrun','delivery','notification','failedpayment','auditlog','pricehistory','transactions','globalsettings')
      AND data_type LIKE 'timestamp%'
  LOOP
    EXECUTE format('UPDATE %I SET %I = %I + $1', col.table_name, col.column_name, col.column_name) USING shift;
  END LOOP;
END
$$;

COMMIT;
